export const CIRCLE_SCENES=CIRCLE_LINES.flatMap(line=>line.beats.map((beat,index)=>({id:`circle-${line.key}-${index}`,line,index,...beat,npc:line.cast[0],other:line.cast[1]})));
const previous=s=>`circle-${s.line.key}-${s.index-1}`;
function sugarPartner(run) {
  const cast=['raina','mika'];
  return cast.find(id=>run.storyFlags['circle-partner:'+id]) || cast.find(id=>run.relationships[id].status==='sugar');
}
export function circleReady(run,s) {
  if(!s || run.storySeen.includes(s.id) || run.day<s.line.day+s.index*3)return false;
  if(!s.line.cast.every(id=>run.relationships[id]?.introduced && !departureContactReason(run,id)))return false;
  if(s.line.sugar) {
    const partner=sugarPartner(run);
    if(!partner || run.relationships[partner].status!=='sugar' || run.departures['player:'+partner]?.resolution==='active')return false;
  }
  if(s.index>0 && (!run.storySeen.includes(previous(s)) || run.day<(run.storyFlags['read:'+previous(s)] || run.day)+2))return false;
  return true;
}
export function circleFor(run,npc,mode) {
  if(run.storyFlags.lastCircleDay===run.day)return null;
  const candidates=CIRCLE_SCENES.filter(s=>circleReady(run,s) && (['talk','date'].includes(mode)?s.line.cast.includes(npc):mode==='explore' && s.line.world===run.world));
  // 接续已开启的故事，避免开了很多头却一直遇不到后章。
  candidates.sort((a,b)=>(b.index>0)-(a.index>0) || a.line.day-b.line.day);
  const s=candidates[0];return s?{type:'scene',id:s.id,npc:s.npc,other:s.other}:null;
}
export function circleScene(run,p) {
  const base=CIRCLE_SCENES.find(s=>s.id===p.id);if(!base)return null;
  const s=circleBranch(run,base);
  const names=s.line.cast.map(id=>PEOPLE.find(p=>p.id===id).name).join('、');
  const before=run.storyFlags['choice:'+previous(s)];
  const prior=s.index>0?CIRCLE_SCENES.find(x=>x.id===previous(s)):null;
  const echo=prior?`之前，你选择了「${prior.branches[before ?? 0][0]}」。${before===2?'那次没能谈妥的地方还在。过了几晚，两人重新征求了彼此的意见，才继续这段谈话。':'那次的选择仍然留在你们的聊天记录里。'}\n\n`:'';
  const partner=s.line.sugar?sugarPartner(run):null;
  const text=s.text.replaceAll('砂糖搭档','搭档').replaceAll('搭档',partner?PEOPLE.find(p=>p.id===partner).name:'搭档');
  return {id:s.id,npc:s.npc,other:s.other,title:s.title,subtitle:`${s.line.name} · ${s.index+1} / 3`,text:`这是你与${names}通过好友消息和共享记录接续的故事，可以在不同世界继续。\n\n`+echo+text,choices:s.branches.map(([label,text],i)=>({label,text,effects:i===0?{mood:2}:i===1?{balance:2}:{},rel:i===2?{tension:3}:{trust:2},otherRel:i===2?{tension:3}:{trust:2},npcLinkDelta:i===2?-2:2,pairEffects:i===2?{trust:-2,tension:3}:{trust:2,tension:-2},...(partner?{circlePartner:partner}:{}),outcome:'circle-read'}))};
}
export function validateCircleHistory(run) {
  const partnerKeys=Object.keys(run.storyFlags).filter(k=>k.startsWith('circle-partner:'));
  if(partnerKeys.length>1 || partnerKeys.some(k=>!['circle-partner:raina','circle-partner:mika'].includes(k) || run.storyFlags[k]!==true))return false;
  if(run.storyFlags.lastCircleDay!==undefined && (!Number.isInteger(run.storyFlags.lastCircleDay) || run.storyFlags.lastCircleDay<1 || run.storyFlags.lastCircleDay>run.day))return false;
  for(const s of CIRCLE_SCENES) {
    const seen=run.storySeen.includes(s.id),day=run.storyFlags['read:'+s.id],choice=run.storyFlags['choice:'+s.id];
    if(seen!==(day!==undefined) || seen!==(choice!==undefined))return false;
    if(!seen)continue;
    if(!s.line.cast.every(id=>run.relationships[id]?.introduced) || day<s.line.day+s.index*3)return false;
    if(s.index>0 && (!run.storySeen.includes(previous(s)) || day<run.storyFlags['read:'+previous(s)]+2))return false;
    if(s.line.sugar && partnerKeys.length!==1)return false;
  }
  return partnerKeys.length===0 || run.storySeen.includes('circle-sugar-0');
}
